    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Konfigurera systemomfattande inställningar: bas-URL, säkerhet, standardspråk, tidszon, standardvärden för riskpoängsättning och mer.',
    'SettingsPreferencesDesc'             => 'Standardvärden och beteendeinställningar i hela SimpleRisk: språk, tidszon, revisionsstatusar, krav på riskmappning, växlar för gränssnittets beteende och liknande.',
