    'HealthCheckDesc'                     => 'Diagnostisera systemets status: PHP-version, tillägg, filbehörigheter, databasanslutning, cron-schema och aktiveringar av Extras.',
    'AnnouncementsDesc'                   => 'Skriv och hantera bannermeddelanden som är synliga för alla användare.',
    'RegisterAndUpgradeDesc'              => 'Registrera din SimpleRisk-installation, ange eller förnya en prenumerationsnyckel och aktivera Core/Extra-uppgraderingar med ett klick.',
    'QueueMonitorDesc'                    => 'Kontrollera kön för bakgrundsjobb: väntande, pågående och misslyckade jobb.',
    'ExtrasDesc'                          => 'Aktivera, inaktivera och konfigurera SimpleRisk Extras (betalda tillägg).',
    'ArtificialIntelligenceExtraDesc'     => 'Extra-programmet för artificiell intelligens erbjuder förbättrad riskanalys (inklusive FAIR-bedömningar) och anpassad dokumentation.',
    'CustomizationExtraDesc'              => 'Extrat Anpassning gör det möjligt att lägga till och ta bort olika typer av fält och dynamiskt skapa anpassade sidmallar.',
    'NotificationExtraDesc'               => 'Extrat E-postavisering gör det möjligt för SimpleRisk att skicka e-postaviseringar när risker skickas in, ändras eller på annat sätt åtgärdas. Detta extra kan också läggas till som ett schemalagt skript för att skicka regelbundna påminnelser när risker är redo för en ledningsgranskning. I produkten SimpleRisk Core, utan detta extra, kommuniceras inga aviseringar utanför själva verktyget.',
    'VulnerabilityManagementExtraDesc'    => 'Extrat Sårbarhetshantering ger kunder möjlighet att integrera sin SimpleRisk-instans med Qualys, Tenable.io eller Rapid7 Nexpose/InsightVM och importera både tillgångs- och sårbarhetsdata till SimpleRisk. Därifrån kan du välja vilka webbplatser du vill omfatta, bestämma vilka sårbarhetspoäng som ska importeras och prioritera vilka sårbarheter som omvandlas till risker för att spåra dem.',
    'IncidentManagementExtraDesc'         => 'Extrat Incidenthantering bygger på NIST 800-61 Computer Security Incident Handling Guide och ger funktioner för incidenthantering direkt i SimpleRisk-systemet.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Byt namn på SimpleRisk-terminologin (Risk, Tillgång, Ramverk, etc.) i hela användargränssnittet.',
    'RiskConfigurationDesc'               => 'Konfigurera riskpoängregler: nivåer, aptit, tröskelvärden för SLA och de klassiska/bidragande riskformlerna.',
    'RiskAndThreatCatalogDesc'            => 'Underhåll katalogen över risk- och hotvärden som används i rullgardinsmenyer.',
    'AddAndRemoveValuesDesc'              => 'Hantera rullgardinsmenyvärden för riskfält: plats, källa, kategori, team, teknik med mera.',
    'AssetValuationDesc'                  => 'Konfigurera tillgångsvärderingsskalan och åsidosättningar för värdering per tillgång.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Lägg till, redigera, inaktivera och återställ användare; hantera lösenordspolicy.',
    'RoleManagementDesc'                  => 'Definiera roller och de behörigheter som varje roll ger.',
    'TeamManagementDesc'                  => 'Skapa och hantera team som används för filtrering av postsynlighet.',
    'SeparationExtraDesc'                 => 'Extrafunktionen för teambaserad separation begränsar riskvisning till endast de användare som är medlemmar i det team som risken är tilldelad. I SimpleRisk Core-produkten kan alla användare se alla risker utan denna extrafunktion.',
    'CustomAuthenticationExtraDesc'       => 'Extrafunktionen för anpassad autentisering ger stöd för Active Directory- och SAML-autentisering. I SimpleRisk Core-produkten, utan denna extrafunktion, är det enda alternativet att skapa nya användare i SimpleRisk-identitetsdatabasen.',
    'EncryptionExtraDesc'                 => 'Extrat Krypterad databas genererar en slumpmässig AES-256-bitars krypteringsnyckel och använder den för att kryptera känslig text innan den infogas i SimpleRisk-databasen. Detta förhindrar att någon kan visa eller ändra data utan att använda SimpleRisk-applikationen direkt.',
    'OrganizationManagementDesc'          => 'Extrat Organisationshierarki gör det möjligt att definiera flera affärsenheter som kan innehålla valfritt antal team. Användare kan sedan tilldelas över ett eller flera team under olika affärsenheter. Detta påverkar en användares möjlighet att se och använda de team, användare och tillgångar som de inte är associerade med.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Massborttagning av risker. Använd sparsamt – borttagningar är permanenta.',
    'AuditTrailDesc'                      => 'Sök i och exportera systemets revisionslogg över användaråtgärder.',
    'ImportExportExtraDesc'               => 'Extrat Import-Export ger möjlighet att importera data till SimpleRisk genom att mappa fält i en CSV-fil till fält i SimpleRisk-databasen. Det kan användas för att importera revisionsresultat från ett kalkylblad från tredje part, resultat från sårbarhetsskanningar från ett annat verktyg, tillgångar från din CMDB och mer. Extrat ger också möjlighet att exportera CSV-filer från SimpleRisk som innehåller risker, mitigeringar, granskningar eller en kombinerad rapport över alla tre.',
    'JiraExtraDesc'                       => 'Extrat Jira-integrering ger användare möjlighet att integrera tvåvägs med en Jira-instans. Det gör det möjligt att koppla risker till Jira-ärenden samt synkronisera deras data, status och kommentarer.',
    'APIExtraDesc'                        => 'API Extra låter kunder använda ett RESTful API för att skapa skriptbaserade interaktioner med andra applikationer för att få avancerad automatisering och utnyttja befintlig infrastruktur.',
    'AdvancedSearchExtraDesc'             => 'Extrat Avancerad sökning gör om sökrutan i det övre fältet till en sökning över risker, ramverk, kontroller, dokument, undantag, tester, revisioner, tillgångar och tillgångsgrupper, med en fullständig sökningssida för att gå igenom resultaten. Det visar bara poster som användaren får se.',
    'AssessmentsExtraDesc'                => 'Extrat Riskbedömning ger användare möjlighet att definiera kontakter, skapa frågor (inklusive logik), sammanställa flera frågor med en frågeformulärsmall, skapa frågeformulär och skicka dem till kontakter, visa frågeformulärsresultaten, lägga till risker baserat på dessa resultat, jämföra resultaten över tid, importera och exportera externt anpassade bedömningar samt granska revisionsspåret för riskbedömningen.',
    'ActiveAssessmentsDesc'               => 'Visa och hantera bedömningar som för närvarande pågår.',
    'WorkflowsExtraDesc'                  => 'Extrat Arbetsflöden ger en visuell, händelsedriven arbetsflödesmotor som automatiserar åtgärder inom riskhantering som svar på händelser i SimpleRisk. Du kan utforma arbetsflöden som utlöses av ändringar – till exempel att en risk skickas in, uppdateras eller granskas – för att dirigera godkännanden, tilldela arbete och hålla din process igång utan manuella ingrepp.',

    // Configure Hub - tile descriptions (frameworks category)
