    'ApplicabilityScopeNote' => 'Det här beslutet gäller endast inom "{$framework}". Samma kontroll kan förbli tillämplig i ett annat ramverk.',
    'ApplicabilityAppliesToSelected' => 'Det registreras för de {$n} kontroller som är valda på den här sidan.',
    'ApplicabilityAppliesToAllFiltered' => 'Det registreras för alla {$n} kontroller som matchar de nuvarande filtren, inklusive dem på andra sidor.',
    // Per-state hints under the segmented control. The "applicable" one is the
    // load-bearing sentence of the whole modal, and the SoA audit-readiness work
    // rewrote it: an applicable control MAY now carry its own reasons and
