    'DeleteControlsPreviewKeptOnly' => 'Alla {$n} kontroller kommer att tas bort. Detta kan inte ångras. Testresultat behålls för revisionshistoriken.',
    'DeleteControlsPreviewRemovedOnly' => '{$n} kontroll(er) kommer att tas bort. Detta kan inte ångras.',
