    // 'ApplicabilityDecidedBy'/'DecidedOn', and the plain 'Framework',
    // 'ControlNumber', 'ControlName', 'Justification', 'Evidence', 'Reason',
    // 'Provider', 'Total', 'Controls' and 'Export' keys. Only strings with no
