    'SoaMissingInclusionJustification' => 'Ingen standardmotivering för inkludering har registrerats. Tillämpliga kontroller utan kopplade risker får en generisk motivering i stället för din egen.',
    'SoaEditFrameworkToAdd' => 'Lägg till dem i ramverket',

    // Opened from the Reporting Hub, which cannot supply a framework. A picker,
